#include <iostream>
#include <string>
#include <regex>
#include <vector>

int main() {
    int n;
    std::string s;
    std::cin >> n >> s;

    std::regex pattern("\\([a-zA-Z_]*\\)");
    std::string replacedString = std::regex_replace(s, pattern, "_");

    std::regex split_pattern("_+");
    std::sregex_token_iterator iter(replacedString.begin(), replacedString.end(), split_pattern, -1);
    std::sregex_token_iterator end;

    int maxLengthFound = 0;
    for (; iter != end; ++iter) {
        std::string part = *iter;
        if (part.length() > maxLengthFound) {
            maxLengthFound = part.length();
        }
    }
    std::cout << maxLengthFound << std::endl;

    int totalCount = 0;
    bool inParen = false;
    int startIdx = -1, endIdx = -1;
    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (ch == '(') {
            inParen = true;
            startIdx = i;
        } else if (ch == ')' && inParen) {
            inParen = false;
            endIdx = i;
            std::string insideStr = s.substr(startIdx + 1, endIdx - startIdx - 1);
            if (!insideStr.empty()) {
                std::sregex_token_iterator inner_iter(insideStr.begin(), insideStr.end(), split_pattern, -1);
                int segmentsInsideCount = 0;
                for (; inner_iter != end; ++inner_iter) {
                    segmentsInsideCount++;
                }
                // Adjust count if insideStr starts with '_'
                if (!insideStr.empty() && insideStr[0] == '_') {
                    segmentsInsideCount -= 1;
                }
                totalCount += segmentsInsideCount;
            }
        }
    }
    std::cout << totalCount << std::endl;

    return 0;
}
